CREATE TABLE workspaces (id VARCHAR(36) PRIMARY KEY, type VARCHAR(20) NOT NULL, name VARCHAR(200) NOT NULL, vat_number VARCHAR(20), address VARCHAR(300), status VARCHAR(24) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE accounts (id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, name VARCHAR(200) NOT NULL, role VARCHAR(20) NOT NULL, password_hash VARCHAR(100) NOT NULL, status VARCHAR(20) NOT NULL, verified BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (workspace_id) REFERENCES workspaces(id));
CREATE TABLE sessions (digest VARCHAR(64) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, expires_at TIMESTAMP NOT NULL, FOREIGN KEY (user_id) REFERENCES accounts(id) ON DELETE CASCADE);
CREATE TABLE account_tokens (digest VARCHAR(64) PRIMARY KEY, user_id VARCHAR(36), workspace_id VARCHAR(36), email VARCHAR(254), name VARCHAR(200), purpose VARCHAR(20) NOT NULL, expires_at TIMESTAMP NOT NULL, FOREIGN KEY (user_id) REFERENCES accounts(id) ON DELETE CASCADE, FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE audit_log (id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36), actor_id VARCHAR(36), action VARCHAR(60) NOT NULL, subject_id VARCHAR(200), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_accounts_workspace ON accounts(workspace_id);
CREATE INDEX idx_audit_created ON audit_log(created_at);
